import frappe
from frappe.utils import get_datetime, now_datetime

if doc.work_order:
    bom_no = frappe.db.get_value("Work Order", doc.work_order, "bom_no")
    if bom_no:
        rate = frappe.db.get_value("BOM", bom_no, "custom_piece_rate")
        if rate:
            doc.custom_piece_rate = rate

if doc.qty and doc.custom_piece_rate:
    doc.total_amount = doc.qty * doc.custom_piece_rate
else:
    doc.total_amount = 0

if doc.start_time and doc.end_time:
    start = get_datetime(doc.start_time)
    end = get_datetime(doc.end_time)
    seconds = (end - start).total_seconds()
    if seconds < 0:
        frappe.throw("结束时间不能早于开始时间")
    doc.duration = seconds

if not doc.get("created_at"):
    doc.created_at = now_datetime()
